using System;

namespace StdbModule;

public static partial class PortugueseQuotes
{
    public static class JoséSaramago
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Sentir como uma perda irreparável o acabar de cada dia. Provavelmente, é isto a velhice.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Eu, no fundo, não invento nada. Sou apenas alguém que se limita a levantar uma pedra e a pôr à vista o que está por baixo. Não é minha culpa se de vez em quando me saem monstros.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Estamos usando nosso cérebro de maneira excessivamente disciplinada, pensando só o que é preciso pensar, o que se nos permite pensar.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Nossa maior tragédia é não saber o que fazer com a vida.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Por causa e em nome de Deus é que se tem permitido e justificado tudo, principalmente o mais horrendo e cruel.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Por que, para que e, a mais importante, para quem, são as três perguntas fundamentais que deveríamos fazer ao primeiro-ministro, ao professor, ao pai, ao filho, quase a propósito de tudo o que ocorre. O problema é que isso dá um pouco de trabalho.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Se começássemos a dizer claramente que a democracia é uma piada, um engano, uma fachada, uma falácia e uma mentira, talvez pudéssemos nos entender melhor.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Escrevo para \"tentar entender, e porque não tem nada melhor para fazer\"", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O universo não tem notícia da nossa existência.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Há uma pergunta que me parece dever ser formulada e para a qual não creio que haja resposta: que motivo teria Deus para fazer o universo? Só para que num planeta pequeníssimo de uma galáxia pudesse ter nascido um animal determinado que iria ter um processo evolutivo que chegou a isto?", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Não é a pornografia que é obscena, é a fome que é obscena.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "A ignorância está se expandindo de maneira aterradora.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Se sou pessimista é porque o mundo é péssimo, só isso.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O cérebro humano é um grande criador de absurdos. E Deus é o maior deles.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Nem a juventude sabe o que pode, nem a velhice pode o que sabe", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Duas fraquezas não fazem uma fraqueza maior, fazem uma força nova.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "A vida é assim, faz-se muito de coisas que acabam, Também se faz de coisas que principiam, Nunca são as mesmas.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "As coisas que parecem ter passado são as que nunca acabam de passar", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Ainda que te possa parecer estranha a comparação, os gestos, para mim, são mais do que gestos, são como desenhos feitos pelo corpo de um no corpo de outro.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O momento das carícias voltou a entrar no quarto, pediu desculpa por ter-se demorado tanto lá fora, Não encontrava o caminho, justificou-se, e, de repente, como aos momentos algumas vezes acontece, tornou-se eterno.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "A pena pior, minha filha, não é a que se sente no momento, é a que se vai sentir depois, quando já não houver remédio, Diz-se que o tempo tudo cura, Não vivemos bastante para tirar-lhe a prova.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Não se pode trabalhar num esgoto sem cheirar a esgoto", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Cegueira também é isto, viver num mundo onde se tenha acabado a esperança.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Se não formos capazes de viver inteiramente como pessoas, ao menos, façamos tudo para não viver inteiramente como animais.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Sem futuro, o presente não serve para nada, é como se não existisse, Pode ser que a humanidade venha a conseguir viver sem olhos mas então deixará de ser humanidade.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O mundo caridoso e pitoresco dos ceguinhos acabou, agora é o reino duro, cruel e implacável dos cegos.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "A maior dificuldade para chegar a viver razoavelmente no inferno é o cheiro que lá há.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Perguntar de que morreu alguém é estúpido, com o tempo a causa esquece, só uma palavra fica, Morreu", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Na morte a cegueira é igual para todos.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Quando a aflição aperta, quando o corpo se nos desmanda de dor e angústia, então é que se vê o animalzinho que somos.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O costume de cair endurece o corpo, ter chegado ao chão, só por si, já é um alívio, Daqui não passarei.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Dentro de nós há uma coisa que não tem nome, essa coisa é o que somos.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Se podes olhar, vê. Se podes ver, repara.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Penso que não cegámos, penso que estamos cegos, Cegos que vêem, Cegos que, vendo, não vêem.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "a fé, abençoada seja ela para todo sempre, além de arredar montanhas do caminho daqueles que do seu poder se beneficiam, é capaz de atrever-se às águas mais torrenciais e sair delas enxuta.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Aqui, cada um com seu desgosto e todos com a mesma pena.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "...é o que as palavras simples têm de simpático, não sabem enganar.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O filho de José e de Maria nasceu como todos os filhos dos homens, sujo de sangue de sua mãe, viscoso das suas mucosidades e sofrendo em silêncio. Chorou porque o fizeram chorar, e chorará por esse mesmo e único motivo.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Então Jesus voltou lentamente o rosto para ela e disse. Não conheço mulher. Maria segurou-lhe as mãos, Assim temos de começar todos, homens que não conheciam mulher, mulheres que não conheciam homem, um dia o que sabia ensinou, o que não sabia aprendeu.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Ninguém na vida teve tantos pecados que mereça morrer duas vezes.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Enferrujam-se os arames e os ferros, cobrem-se os panos de mofo, detrança-se o vime ressequido, obra que em meio ficou não precisa envelhecer para ser ruína.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Além da conversa das mulheres, são os sonhos que seguram o mundo na sua órbita. Mas são também os sonhos que lhe fazem um coroa de luas, por isso o céu é o resplendor que há dentro da cabeça dos homens, se não é a cabeça dos homens o próprio e único céu", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Talvez as lágrimas não sejam mais do que isso, o alívio de uma ofensa", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Voando a máquina, todo o céu será música", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Abençoem-se um ao outro, é quanto basta, pudessem todas as bênçãos como essa ser", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Não há nada mais triste que uma ausência (...), só fica uma pungente melancolia, esta que faz (...) sentar ao cravo e tocar um pouco, quase nada, apenas passando os dedos pelas teclas como se estivessem olhando um rosto quando já as palavras foram ditas ou são de menos.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "os homens são anjos nascidos sem asas, é o que há de mais bonito, nascer sem asas e fazê-las crescer, isso mesmo fizemos com o cérebro, se a ele fizemos", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "para o Santo Ofício não há vontades, há só almas", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "José Anaiço está ao lado de Joana Carda mas não lhe toca, compreende que não deve tocar-lhe, ela compreende-o também, há momentos em que mesmo o amor deve conformar-se com a sua insignificância, perdoai que assim reduzamos o extremo dos afetos a quase nada, ele que em outras ocasiões é quase tudo.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Dificílimo acto é o de escrever, responsabilidade das maiores (...)", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Basta pensar no extenuante trabalho que será dispor por ordem temporal os acontecimentos, primeiro este, depois aquele, ou, se tal mais convém às necessidades do efeito, o sucesso de hoje posto antes do episódio de ontem, e outras não menos arriscadas acrobacias (...)", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "(...)os motivos, de que adianta falar de motivos, às vezes basta um só, outras vezes nem juntando todos, se as vidas de cada um de você não lhes ensinaram isto, coitados, e digo vidas, não vida, porque temos várias, felizmente vão se matando umas às outras, se não não poderíamos viver.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "As religiões, todas elas, por mais voltas que lhes dermos, não têm outra justificação para existir que não seja a morte, precisam dela como do pão para a boca.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Não foi o que nos habituaram a ouvir, Algo teríamos que dizer para tornar atractiva a mercadoria, Isso quer dizer que em realidade não acreditam na vida eterna, Fazemos de conta.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Com as palavras todo cuidado é pouco, mudam de opinião como as pessoas.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Porque as palavras, se não o sabe, movem-se muito, mudam de um dia para o outro, são instáveis como sombras, sombras elas mesmas, que tanto estão como deixaram de estar, bolas de sabão, conchas de que mal se sente a respiração, troncos cortados.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "A propósito, não resistiremos a recordar que a morte, por si mesma, sozinha, sem qualquer ajuda externa, sempre matou muito menos que o homem.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "A morte conhece tudo a nosso respeito, e talvez por isso seja triste.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "A prudência só serve para adiar o inevitável, mais cedo ou mais tarde acaba por se render.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "De Deus e da morte não se tem contado senão histórias, e esta é mais uma delas.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "É assim a vida, vai dando com uma mão até que chega o dia em que tira tudo com a outra.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Saberemos cada vez menos o que é um ser humano.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O corpo que sonha é real, portanto, salvo opinião mais autorizada, também tem de ser real o sonho que ele estiver a sonhar.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "... como se o tempo houvesse encolhido todo, de trás para diante e de diante para trás, comprimido em um instante compacto...", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O tempo pusera-se a contar os dias desde o princípio, agora usando a tábua de multiplicação para tirar o atraso. (...) O tempo, ainda que os relógios queiram convencer-nos do contrário, não é o mesmo para toda gente.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Em rigor, não tomamos decisões, são as decisões que nos tomam a nós", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O acaso não escolhe, propõe", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O que dá o verdadeiro sentido ao encontro é a busca e que é preciso andar muito para alcançar o que está perto.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O tempo psicológico não corresponde ao tempo matemático.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "... a efetiva impossibilidade de medir esse tempo a que chamamos de alma...", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Não creio que haja maior respeito que chorar por alguém que não se conheceu.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Aproximou-se duma sepultura e tomou a atitude de alguém que estivesse a meditar profundamente na irremissível precariedade da existência, na vacuidade de todos os sonhos e de todas as esperanças, na fragilidade absoluta das glórias mundanas e divinas.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Gostar é provavelmente a melhor maneira de ter, ter deve ser a pior maneira de gostar.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Quero encontrar a ilha desconhecida, quero saber quem sou quando nela estiver.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Como escreveu o poeta, os pinheiros bem acenam, mas o céu não lhes responde. Também não responde aos homens, apesar de estes, em sua maioria, saberem desde pequenos as orações precisas, o problema está em acertar com uma língua que deus seja capaz de entender.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Sempre chegamos ao sítio aonde nos esperam.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Todo o romance é isso, desespero, intento frustrado de que o passado não seja coisa definitivamente perdida. Só não se acabou ainda de averiguar se é o romance que impede o homem de esquecer-se ou se é a impossibilidade do esquecimento que o leva a escrever romances.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Orientamo-nos por normas geradas segundo consensos, e domínios, mete-se pelos olhos dentro que variando o domínio varia o consenso, Não deixas saída, Porque não há saída, vivemos num quarto fechados e pintamos o mundo e o universo nas paredes dele.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Um homem avança por espaços que a arquitetura organizou, por salas povoadas de rostos e figuras – e certamente não sai sendo o que era ao entrar, ou mais lhe valera ter passado de largo.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Verificar, simples opinião minha, é a verdadeira regra de ouro.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "acreditamos na importância do que dissemos ou escrevemos até certo ponto, ..., mas entra-nos no corpo a tentação da mudez, a fascinação da imobilidade, estar como estão os deuses, calados e quietos, assistindo apenas.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Se não dissermos as palavras todas, mesmo absurdamente, nunca diremos as necessidades.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "As verdades são muitas e estão umas contra as outras, enquanto não lutarem não se saberá onde está a mentira.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "A verdadeira prisão é aceitar estar preso.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O destino é a ordem suprema, a que os próprios deuses aspiram, E os homens, que papel vem a ser o dos homens, Perturbar a ordem, corrigir o destino, Para melhor, Para melhor ou para pior, tanto faz, o que é preciso é impedir que o destino seja destino.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Estas terras marginais são predilectas do turismo. O viajante não é turista, é viajante. Há grande diferença. Viajar é descobrir, o resto é simples encontrar.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "... se os mouros ainda por cá estivessem, ficaria muito contente, sendo horas de almoçar, se lhe apresentassem uma lista onde pudesse ler: sardinhas assadas", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "[Nicolau] Nasoni era italianíssimo, mas soube entender os méritos do granito lusitano, dar-lhe espaço para melhor chegar aos olhos, alternando o escuro da pedra moldurante com a cal dos rebocos.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Como podem homens sem Deus serem bons? Como podem homens com Deus serem tão maus?", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "O senhor ainda sente necessidades de ajustar contas com Deus, mesmo acreditando que ele só existe na cabeça das pessoas? Deus não existe fora da cabeça das pessoas que nele creem.", Author = "José Saramago" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_Saramago", Text = "Há uma tendência autoritária em muitos países. Nada restou dos ideais. A esquerda sofre uma espécie de tentação maligna que é a fragmentação. Não vejo nada mais estúpido do que a esquerda. Uns enfrentam os outros, por grupos, por partidos, por opções.", Author = "José Saramago" },
        };
    }
}